CREATE TRIGGER royal_allocate_number AFTER INSERT ON orders WHEN NEW.order_number IS NULL BEGIN UPDATE counters SET value=value+1 WHERE name='order'; UPDATE orders SET order_number=(SELECT value FROM counters WHERE name='order') WHERE id=NEW.id; END;
CREATE TRIGGER royal_stock_check BEFORE INSERT ON orders WHEN NOT EXISTS(SELECT 1 FROM orders WHERE id=NEW.id) BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.items) j JOIN products p ON p.id=json_extract(j.value,'$.id') WHERE p.stock>=0 AND p.stock<json_extract(j.value,'$.quantity')) THEN RAISE(ABORT,'insufficient_stock') END; END;
CREATE TRIGGER royal_stock_debit AFTER INSERT ON orders BEGIN UPDATE products SET stock=stock-(SELECT json_extract(j.value,'$.quantity') FROM json_each(NEW.items) j WHERE json_extract(j.value,'$.id')=products.id) WHERE stock>=0 AND id IN(SELECT json_extract(value,'$.id') FROM json_each(NEW.items)); END;
CREATE TRIGGER royal_stock_release AFTER UPDATE OF status ON orders WHEN NEW.status='cancelled' AND OLD.status!='cancelled' BEGIN UPDATE products SET stock=stock+(SELECT json_extract(j.value,'$.quantity') FROM json_each(NEW.items) j WHERE json_extract(j.value,'$.id')=products.id) WHERE stock>=0 AND id IN(SELECT json_extract(value,'$.id') FROM json_each(NEW.items)); END;
CREATE TRIGGER royal_capacity_check BEFORE INSERT ON orders WHEN NOT EXISTS(SELECT 1 FROM orders WHERE id=NEW.id) BEGIN SELECT CASE WHEN (SELECT COUNT(*) FROM orders WHERE status IN('new','accepted','preparing','ready'))>=(SELECT MAX(1,CAST(capacity*CASE WHEN busy_mode=1 THEN 0.5 ELSE 1 END AS INTEGER)) FROM settings WHERE id=1) THEN RAISE(ABORT,'capacity_full') END; END;
